*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0b141a;color:#f2f0e9;font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#13252a;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 43%,transparent 35%,rgba(7,14,17,.22) 78%,rgba(5,11,14,.62) 130%);z-index:1}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:74px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,16,19,.78),transparent)}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:37px;height:37px;display:grid;place-items:center;background:#d7ff70;color:#172125;font:900 15px 'Barlow Condensed',sans-serif;transform:skew(-8deg);letter-spacing:-1px}.brand>div{display:grid;gap:1px}.brand b{font:800 17px 'Barlow Condensed',sans-serif;letter-spacing:1.9px}.brand small{font-size:8px;letter-spacing:2px;color:#aab8b4}.match-info{display:flex;align-items:center;gap:11px;font-size:9px;font-weight:700;letter-spacing:1.5px;color:#d9e3dd}.match-info i{height:13px;border-left:1px solid #71817e;margin:0 3px}.match-info #clock{font:700 14px 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#f5f4ed}.live-dot,.eyebrow span{width:7px;height:7px;border-radius:50%;background:#c9fa68;box-shadow:0 0 11px #c9fa68}.icon-btn{background:transparent;border:1px solid rgba(255,255,255,.25);padding:8px 11px;border-radius:2px;font-size:13px;letter-spacing:1px}.icon-btn span{font:700 8px 'DM Sans',sans-serif;vertical-align:1px;letter-spacing:1px;margin-left:4px}.hud{position:absolute;z-index:3;inset:0;pointer-events:none}.left-hud{position:absolute;left:34px;top:102px;display:flex;flex-direction:column;gap:11px;width:210px}.status-card{padding:12px 14px 11px;background:linear-gradient(105deg,rgba(8,18,21,.78),rgba(8,18,21,.3));border-left:2px solid #d5f777;backdrop-filter:blur(4px)}.status-top{display:flex;justify-content:space-between;font:700 10px 'Barlow Condensed';letter-spacing:1.8px;color:#e8ede7;margin-bottom:8px}.status-top span:last-child{font-size:13px;color:#d7ff70}.meter{height:5px;background:rgba(255,255,255,.16);overflow:hidden}.meter-fill{height:100%;transition:width .25s}.health-fill{background:linear-gradient(90deg,#d9f36e,#a8d64d)}.armor-row{display:flex;align-items:center;gap:8px;margin-top:8px;font:700 8px 'Barlow Condensed';letter-spacing:1.4px;color:#9daaa6}.armor-meter{height:3px;flex:1}.armor-fill{background:#75c9d1}.armor-row b{font-size:9px;color:#c6d5d2}.objective{height:43px;display:flex;align-items:center;gap:10px;padding:5px 10px;background:rgba(11,21,24,.57);border:1px solid rgba(255,255,255,.08)}.obj-icon{font-size:20px;color:#d4fc70}.objective>div:last-child{display:grid;gap:2px}.objective small{font-size:7px;font-weight:700;color:#9faeaa;letter-spacing:1.5px}.objective b{font-size:10px;font-weight:600}.center-hud{position:absolute;inset:0;display:grid;place-items:center}.reticle{position:absolute;left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%);opacity:.85}.reticle i{position:absolute;background:#fff;width:2px;height:7px;box-shadow:0 0 3px #000}.reticle i:nth-child(1){top:0;left:12px}.reticle i:nth-child(2){bottom:0;left:12px}.reticle i:nth-child(3){top:10px;left:0;width:7px;height:2px}.reticle i:nth-child(4){top:10px;right:0;width:7px;height:2px}.reticle b{position:absolute;left:11px;top:10px;width:4px;height:4px;border:1px solid rgba(255,255,255,.9);border-radius:50%}.zone-alert{position:absolute;top:20%;font:800 11px 'Barlow Condensed';letter-spacing:2.5px;color:#f4d186;padding:9px 14px;border-top:1px solid rgba(243,192,109,.42);border-bottom:1px solid rgba(243,192,109,.42);background:rgba(36,25,15,.35);opacity:0;transition:opacity .3s}.zone-alert.show{opacity:1}.pickup-prompt{position:absolute;top:calc(50% + 45px);padding:8px 12px;background:rgba(12,21,23,.82);font:700 9px 'Barlow Condensed';letter-spacing:1.4px;color:#dbe5d9}.pickup-prompt b{color:#d7ff70;border:1px solid #d7ff70;padding:2px 5px;margin:0 4px}.pickup-prompt span{color:#fff}.hit-marker{position:absolute;left:50%;top:50%;font:400 25px 'DM Sans';color:#d7ff70;transform:translate(-50%,-50%) scale(.3);opacity:0;text-shadow:0 0 7px #d7ff70}.hit-marker.hit{animation:hit .28s ease-out}@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) scale(.5)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.25)}}.right-hud{position:absolute;right:34px;top:99px;width:168px}.map-card{height:190px;background:rgba(10,20,22,.58);border:1px solid rgba(222,239,222,.25);position:relative;overflow:hidden;box-shadow:0 8px 22px rgba(0,0,0,.2)}#minimap{width:168px;height:168px;display:block}.map-label{height:21px;padding:4px 7px;font:700 8px 'Barlow Condensed';letter-spacing:1.3px;background:rgba(9,17,18,.85)}.map-label span{float:right;color:#c8f76a}.survivors{height:51px;margin-top:8px;padding:7px 10px;display:flex;align-items:center;gap:8px;background:rgba(8,17,20,.75);border-left:2px solid #d6f46f}.survivors .survivor-icon{font-size:16px;color:#d6f46f}.survivors div{display:grid;gap:1px}.survivors b{font:700 16px 'Barlow Condensed';line-height:15px}.survivors small{font-size:7px;letter-spacing:1px;color:#9eadaa;white-space:nowrap}.survivors i{height:24px;border-left:1px solid rgba(255,255,255,.2);margin:0 2px}.bottom-hud{position:absolute;bottom:23px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:10px}.weapon-card{height:63px;width:300px;display:flex;align-items:center;padding:8px 13px;background:linear-gradient(100deg,rgba(9,19,21,.9),rgba(10,22,24,.64));border-top:1px solid rgba(230,245,221,.25);position:relative}.weapon-icon{width:34px;height:34px;display:grid;place-items:center;font-size:24px;color:#d6f76b;border:1px solid rgba(216,246,112,.45);margin-right:10px}.weapon-name{display:grid;gap:2px}.weapon-name small{font-size:7px;letter-spacing:1.6px;color:#9ca9a2}.weapon-name b{font:700 14px 'Barlow Condensed';letter-spacing:1px}.weapon-name b span{color:#d8f675}.ammo{margin-left:auto;display:flex;align-items:baseline;gap:4px}.ammo b{font:700 27px 'Barlow Condensed';color:#f7f5ec}.ammo span{font-size:10px;color:#8f9b96}.ammo i{font-style:normal}.reload-indicator{position:absolute;right:13px;top:-18px;font:700 8px 'Barlow Condensed';letter-spacing:1.6px;color:#d7fa6b;opacity:0}.reload-indicator.show{opacity:1}.controls-hint{white-space:nowrap;font-size:8px;letter-spacing:1px;font-weight:700;color:rgba(238,242,229,.7)}.controls-hint span{padding:0 5px;color:#d8f675}kbd{font:700 8px 'DM Sans';padding:3px 4px;margin-right:2px;border:1px solid rgba(255,255,255,.35);background:rgba(3,10,12,.3);border-radius:2px}.damage-flash{position:absolute;inset:0;border:0 solid rgba(244,65,57,0);transition:border .1s;pointer-events:none}.damage-flash.on{border:10px solid rgba(235,67,55,.45)}.screen{position:absolute;z-index:5;inset:0;display:flex;align-items:center;padding:9vh 11vw;background:linear-gradient(90deg,rgba(7,14,16,.91) 0%,rgba(7,14,16,.77) 38%,rgba(7,14,16,.24) 72%,rgba(7,14,16,.08));}.intro-copy{max-width:530px;margin-top:18px}.eyebrow{display:flex;align-items:center;gap:9px;font-size:9px;font-weight:700;letter-spacing:2.2px;color:#c7d0c8}.intro-copy h1,.end-card h2{margin:18px 0 13px;font:900 clamp(58px,8vw,104px)/.79 'Barlow Condensed',sans-serif;letter-spacing:-2px;color:#f1f0e6}.intro-copy h1 em,.end-card h2 em{font-style:normal;color:#d6f574}.intro-copy p{font-size:13px;line-height:1.8;color:#bec8c1;margin:20px 0 21px}.intro-stats{display:flex;align-items:center;gap:20px;margin:23px 0 27px}.intro-stats div{display:grid;gap:1px}.intro-stats b{font:700 23px 'Barlow Condensed';color:#eaf1dd}.intro-stats small{font-size:7px;letter-spacing:1.5px;color:#99aaa3}.intro-stats i{height:26px;border-left:1px solid rgba(255,255,255,.2)}.primary-btn{height:48px;min-width:242px;display:flex;align-items:center;justify-content:space-between;gap:32px;padding:0 17px;background:#d7f576;border:0;color:#152125;cursor:pointer;font:800 11px 'Barlow Condensed';letter-spacing:1.9px;transition:background .2s,transform .2s}.primary-btn:hover{background:#e5ff9b;transform:translateY(-2px)}.primary-btn b{font:400 21px 'DM Sans'}.intro-foot{margin-top:42px;font-size:8px;font-weight:700;letter-spacing:1.6px;color:#9eaaa2}.intro-foot span{color:#d7f576;padding:0 6px}.intro-side{position:absolute;right:11vw;bottom:14%;display:flex;flex-direction:column;align-items:flex-start;color:#edf2e8}.side-line{height:53px;border-left:1px solid #d7f576;margin-bottom:14px}.intro-side>span{font:700 8px 'Barlow Condensed';letter-spacing:2px;color:#d5ee85}.intro-side b{font:800 31px/0.93 'Barlow Condensed';letter-spacing:1px;margin-top:13px}.intro-side small{margin-top:14px;font-size:8px;line-height:1.6;letter-spacing:1px;color:#abb8ae}.end-screen{z-index:6;justify-content:center;text-align:center;background:rgba(7,14,16,.7);backdrop-filter:blur(5px);padding:20px}.end-card{padding:45px 56px;background:rgba(10,20,21,.8);border:1px solid rgba(220,244,204,.18);box-shadow:0 20px 80px #071013}.end-card .eyebrow{justify-content:center}.end-card h2{font-size:72px;margin:22px 0 12px}.end-card p{color:#bec8c1;font-size:12px}.result-stats{display:flex;justify-content:center;gap:45px;margin:24px 0}.result-stats div{display:grid;gap:3px}.result-stats small{font-size:8px;letter-spacing:1.5px;color:#99aaa3}.result-stats b{font:700 23px 'Barlow Condensed'}.end-card .primary-btn{margin:auto}.toast{position:absolute;z-index:6;top:28%;left:50%;transform:translateX(-50%) translateY(-8px);padding:9px 17px;background:rgba(10,19,21,.88);border:1px solid rgba(215,245,118,.35);font:700 9px 'Barlow Condensed';letter-spacing:1.5px;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}.pause-tag{position:absolute;z-index:4;left:50%;top:62%;transform:translateX(-50%);font:700 9px 'Barlow Condensed';letter-spacing:1.5px;background:rgba(8,17,18,.8);padding:9px 13px}.pause-tag span{margin-left:10px;color:#d7f576}.mobile-controls{display:none}.mobile-controls .look-hint{position:absolute;right:21%;bottom:139px;color:rgba(255,255,255,.45);font:700 8px 'Barlow Condensed';letter-spacing:1.5px}
@media(max-width:760px){.topbar{height:56px;padding:0 15px}.brand-mark{width:30px;height:30px;font-size:12px}.brand b{font-size:14px}.brand small{font-size:7px}.match-info{font-size:7px;gap:6px;letter-spacing:1px}.icon-btn{padding:6px 8px}.icon-btn span{display:none}.left-hud{top:68px;left:12px;width:160px;gap:6px}.status-card{padding:8px 9px}.objective{height:37px}.right-hud{right:11px;top:68px;width:112px}.map-card{height:132px}.map-label{height:18px;font-size:7px;padding:4px}.map-card canvas{width:112px;height:112px}.survivors{height:44px;padding:5px 7px;gap:6px}.survivors small{font-size:6px}.survivors b{font-size:14px}.survivors .survivor-icon{font-size:12px}.bottom-hud{bottom:11px;gap:6px}.weapon-card{width:230px;height:52px;padding:6px 9px}.weapon-icon{height:29px;width:29px;margin-right:7px}.weapon-name b{font-size:12px}.ammo b{font-size:23px}.controls-hint{display:none}.zone-alert{top:24%;font-size:9px}.screen{padding:10vh 8vw;background:linear-gradient(90deg,rgba(7,14,16,.86),rgba(7,14,16,.47) 75%,rgba(7,14,16,.25))}.intro-copy{margin-top:50px}.intro-copy h1{font-size:clamp(54px,14vw,83px)}.intro-copy p{font-size:11px}.intro-side{display:none}.intro-stats{gap:13px}.intro-stats b{font-size:19px}.intro-foot{font-size:7px;margin-top:28px}.primary-btn{height:45px;min-width:220px}.mobile-controls{position:absolute;z-index:4;inset:0;display:block;pointer-events:none}.stick-zone{position:absolute;left:20px;bottom:92px;width:130px;height:130px;pointer-events:auto;touch-action:none}.stick-base{position:absolute;inset:10px;border-radius:50%;background:rgba(11,22,22,.34);border:1px solid rgba(255,255,255,.28);display:grid;place-items:center}.stick-base:after{content:'';position:absolute;width:3px;height:3px;border-radius:50%;background:#d7f576}.stick-base #stick-knob{width:46px;height:46px;border-radius:50%;background:rgba(214,245,118,.26);border:1px solid rgba(214,245,118,.7);position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)}.mobile-actions{position:absolute;right:18px;bottom:93px;display:flex;align-items:flex-end;gap:8px;pointer-events:auto}.mobile-actions button{width:54px;height:54px;border-radius:50%;border:1px solid rgba(255,255,255,.42);background:rgba(9,20,21,.5);font-size:20px;color:#e7f2db;touch-action:manipulation}.mobile-actions button#mobile-fire{width:68px;height:68px;border-color:#d7f576;background:rgba(215,245,118,.18);font-size:27px}.mobile-actions small{display:block;font:700 6px 'Barlow Condensed';letter-spacing:1px}.look-hint{display:block}.reticle{width:22px;height:22px}.pickup-prompt{top:calc(50% + 35px);font-size:8px}.end-card{padding:33px 23px;width:min(100%,360px)}.end-card h2{font-size:60px}.result-stats{gap:28px}}
@media(max-height:620px) and (min-width:761px){.screen{padding-top:5vh;padding-bottom:5vh}.intro-copy h1{font-size:74px}.intro-copy p{margin:12px 0}.intro-stats{margin:14px 0 18px}.intro-foot{margin-top:24px}.intro-side{bottom:9%}.bottom-hud{bottom:10px}.left-hud{top:82px}.right-hud{top:82px}}

import * as THREE from 'three';

const $ = (id) => document.getElementById(id);
const canvas = $('game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9c5bd');
scene.fog = new THREE.FogExp2('#9cb7ae', 0.0065);
const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.1, 420);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.16;

const hemi = new THREE.HemisphereLight('#d5eee3', '#455a46', 2.0); scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff1cf', 3.2); sun.position.set(-65, 95, 55); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -100; sun.shadow.camera.right = 100; sun.shadow.camera.top = 100; sun.shadow.camera.bottom = -100; sun.shadow.bias = -0.0004; scene.add(sun);
const fill = new THREE.DirectionalLight('#9cced1', 1.1); fill.position.set(45, 28, -50); scene.add(fill);
const mat = (color, roughness = 1, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const materials = {
  grass: mat('#74895d'), grassLight: mat('#91a76a'), soil: mat('#716c50'), rock: mat('#778276'), darkRock: mat('#59645c'),
  bark: mat('#5d4a36'), leaf: mat('#31594a'), leaf2: mat('#47765a'), sand: mat('#bca779'), water: new THREE.MeshStandardMaterial({color:'#3e8488', roughness:.34, metalness:.1}),
  roof: mat('#687675'), wall: mat('#c5b99c'), blue: mat('#628f91'), orange: mat('#be764e'), metal: mat('#4c6262',.55,.28), crate: mat('#a8844f'), dark: mat('#273537')
};
let seed = 17041;
function rand(){ seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }
function range(a,b){ return a + rand()*(b-a); }
function terrainHeight(x,z){ return 0.35*Math.sin(x*.075)*Math.cos(z*.08) + 0.27*Math.sin((x+z)*.12) + 0.18*Math.cos(z*.19); }
function mesh(geometry, material, parent=scene, x=0,y=0,z=0){ const o=new THREE.Mesh(geometry,material); o.position.set(x,y,z); o.castShadow=true; o.receiveShadow=true; parent.add(o); return o; }
function box(parent, x,y,z, sx,sy,sz, material){return mesh(new THREE.BoxGeometry(sx,sy,sz),material,parent,x,y,z);}

// A wide, low-poly island with a sandy shoreline, ringed by open water.
const water = mesh(new THREE.PlaneGeometry(900,900), materials.water, scene, 0,-4.2,0); water.rotation.x=-Math.PI/2; water.receiveShadow=false;
const grid=120, worldSize=210, positions=[], colors=[], indices=[];
const cGrass=new THREE.Color('#778a60'), cHigh=new THREE.Color('#657959'), cSand=new THREE.Color('#bda87d'), cRock=new THREE.Color('#777b68');
for(let iz=0;iz<=grid;iz++) for(let ix=0;ix<=grid;ix++){
  const x=(ix/grid-.5)*worldSize, z=(iz/grid-.5)*worldSize, r=Math.sqrt(x*x+z*z), edge=THREE.MathUtils.smoothstep(r,83,104);
  let y=terrainHeight(x,z)*(1-edge)-edge*5.7; if(r<76) y += Math.max(0,1-r/76)*1.5;
  positions.push(x,y,z);
  const col=new THREE.Color(); if(r>75&&r<83) col.copy(cSand); else if(r>83) col.copy(cRock); else col.copy(cGrass).lerp(cHigh,THREE.MathUtils.clamp((y+1)/4,0,.65));
  const variation=(rand()-.5)*.045; col.offsetHSL(0,variation,variation); colors.push(col.r,col.g,col.b);
  if(ix<grid&&iz<grid){const a=iz*(grid+1)+ix,b=a+1,c=a+grid+1,d=c+1;indices.push(a,c,b,b,c,d);}
}
const groundGeo=new THREE.BufferGeometry();groundGeo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));groundGeo.setIndex(indices);groundGeo.computeVertexNormals();
const ground=mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}),scene,0,0,0);ground.castShadow=false;
function groundY(x,z){return terrainHeight(x,z)+.08;}

// Distant headland silhouettes and warm atmospheric light.
for(let i=0;i<34;i++){
  const a=i/34*Math.PI*2, r=102+range(3,13), h=range(5,17), x=Math.cos(a)*r,z=Math.sin(a)*r;
  const rock=mesh(new THREE.DodecahedronGeometry(range(5,11),0),i%3?materials.darkRock:materials.rock,scene,x,-1.7,z);rock.scale.set(1,h/7,1.25);rock.rotation.y=range(0,6);
}

// Hand-built shelters, sheds, and lookout structures make every settlement a landmark.
const landmarks=[];
function makeBuilding(x,z,kind=0,rotation=range(0,Math.PI*2)){
 const g=new THREE.Group(); g.position.set(x,groundY(x,z),z);g.rotation.y=rotation;scene.add(g);landmarks.push(new THREE.Vector3(x,0,z));
 const w=kind===2?10:range(7,10), d=kind===2?7:range(6,9), h=kind===2?5:range(3.4,4.4);
 const wallmat=[materials.wall,materials.blue,materials.orange][kind%3];
 box(g,0,h/2,0,w,h,d,wallmat);box(g,0,h+.16,0,w+0.5,.32,d+.5,materials.roof);
 // contrasting lean-to roof edge and front awning
 box(g,0,h*.72,d/2+.18,w*.56,.13,.55,materials.dark);box(g,-w*.22,h*.58,d/2+.12,1.25,1.8,.12,materials.dark);
 box(g,w*.27,h*.42,d/2+.13,1.2,1.15,.12,materials.dark);
 // bright door panel
 box(g,-w*.1,.95,d/2+.17,1.1,1.9,.18,materials.crate);
 for(let sx of [-1,1]) for(let sz of [-1,1]) box(g,sx*(w/2-.18),.55,sz*(d/2-.18),.28,1.1,.28,materials.dark);
 if(kind===2){
   box(g,0,h+1.5,0,1.1,3,1.1,materials.metal);box(g,0,h+3.1,0,4,.28,4,materials.orange);
   for(let j=0;j<4;j++)box(g,0,h+2.55+j*.12,0,3.8,.025,3.8,materials.roof);
 }
 return g;
}
const settlements=[[-38,-30,0],[-8,-37,1],[32,-26,2],[49,8,0],[22,34,1],[-24,39,2],[-50,9,1],[0,9,0]];
settlements.forEach(([x,z,k])=>makeBuilding(x,z,k));

// Forest clusters: faceted trunks and layered canopies, with a few bright wind flags.
function makeTree(x,z,scale=1){
 const g=new THREE.Group();g.position.set(x,groundY(x,z),z);scene.add(g);
 const trunk=mesh(new THREE.CylinderGeometry(.22*scale,.35*scale,2.1*scale,6),materials.bark,g,0,1*scale,0);trunk.castShadow=true;
 const color=rand()>.5?materials.leaf:materials.leaf2;
 for(let i=0;i<3;i++){const y=(1.65+i*.85)*scale, r=(1.5-i*.32)*scale;const crown=mesh(new THREE.ConeGeometry(r,2.25*scale,7),color,g,0,y,0);crown.rotation.y=range(0,6);}
 if(rand()>.82){const pole=box(g,0,4.9*scale,0,.07,3.1*scale,.07,materials.metal);pole.rotation.z=-.08;const flag=box(g,.65*scale,5.9*scale,0,1.3*scale,.55*scale,.07,materials.orange);flag.rotation.y=.12;}
}
for(let i=0;i<105;i++){
 const a=range(0,Math.PI*2),r=range(20,73),x=Math.cos(a)*r,z=Math.sin(a)*r;
 if(landmarks.some(p=>p.distanceTo(new THREE.Vector3(x,0,z))<9))continue;
 makeTree(x,z,range(.72,1.3));
}
function makeRock(x,z,s=1){const o=mesh(new THREE.DodecahedronGeometry(s,0),rand()>.5?materials.rock:materials.darkRock,scene,x,groundY(x,z)+s*.45,z);o.scale.set(1.3,.75,1);o.rotation.set(range(0,.5),range(0,6),range(0,.5));}
